/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, AppliedUndef, Mul, Pow, SingularityFunction, Sym, mul, rational, singularityintegrate, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.integrals.singularityfunctions", () => {
  it("singularityintegrate(SingularityFunction(x, a, 3), x)", () => {
    const [x, a] = symbols('x a');
    expect(sympyStr(singularityintegrate(SingularityFunction(x, a, rational(3)), x))).toBe('SingularityFunction(x, a, 4)/4');
  });
  it("singularityintegrate(5*SingularityFunction(x, 5, -2), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(singularityintegrate(mul(5, SingularityFunction(x, rational(5), rational(-2))), x))).toBe('5*SingularityFunction(x, 5, -1)');
  });
  it("singularityintegrate(6*SingularityFunction(x, 5, -1), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(singularityintegrate(mul(6, SingularityFunction(x, rational(5), rational(-1))), x))).toBe('6*SingularityFunction(x, 5, 0)');
  });
  it("singularityintegrate(x*SingularityFunction(x, 0, -1), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(singularityintegrate(mul(x, SingularityFunction(x, rational(0), rational(-1))), x))).toBe('0');
  });
  it("singularityintegrate(SingularityFunction(x, 1, -1) * f(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(singularityintegrate(mul(SingularityFunction(x, rational(1), rational(-1)), new AppliedUndef('f', [x])), x))).toBe('f(1)*SingularityFunction(x, 1, 0)');
  });
});

